        byte[] packHeader = [0x00, 0x00, 0x01, 0xBA, 0x44, 0x00, 0x04, 0x00, 0x04, 0x01, 0x01, 0x89, 0xC3, 0xF8];
        var clip = drive.Write("MOV001.MOD", [.. packHeader, .. new byte[64 * 1024]]);
