    // Frame 0 is red and every later frame blue, so a poster's colour tells which frame it came from.
    private static void MakeRedThenBlue(string path, double seconds, int gop, double audioSeconds)
    {
        Run(s_tools.Ffmpeg,
        [
            "-hide_banner", "-loglevel", "error", "-nostdin", "-y",
            "-f", "lavfi", "-i", $"color=c=blue:size=640x360:rate=25:duration={seconds.ToString(CultureInfo.InvariantCulture)},drawbox=c=red:t=fill:enable='eq(n,0)'",
            "-f", "lavfi", "-i", $"sine=frequency=440:duration={audioSeconds.ToString(CultureInfo.InvariantCulture)}",
            "-c:v", "libx264", "-g", gop.ToString(CultureInfo.InvariantCulture), "-pix_fmt", "yuv420p", "-c:a", "aac",
            path,
        ]);
    }

    // As the owner's SD camcorder files (D-084): MPEG-2 video and a declared AC-3 stream that FFmpeg cannot decode, so
    // the file plays without sound. Made by blanking every AC-3 frame in the program stream's private stream 1 packets.
    // Matroska with a video stream, an AC-3 stream and (unless left out) an AAC one. Every AC-3 frame's header then gets an
    // invalid sample-rate code, so FFmpeg reads its packets and decodes none; the container stays intact.
    private static void MakeFileWithUndecodableFirstSound(string path, bool secondSound = true)
    {
        var ac3 = path + ".ac3";
        try
        {
            Run(s_tools.Ffmpeg, ["-hide_banner", "-loglevel", "error", "-nostdin", "-y", "-f", "lavfi", "-i", "anullsrc=r=48000:cl=stereo", "-t", "2", "-c:a", "ac3", ac3]);
            Run(s_tools.Ffmpeg,
            [
                "-hide_banner", "-loglevel", "error", "-nostdin", "-y",
                "-f", "lavfi", "-i", "testsrc=size=320x240:rate=25:duration=2",
                "-f", "ac3", "-i", ac3,
                .. secondSound ? (string[])["-f", "lavfi", "-i", "sine=frequency=440:duration=2"] : [],
                "-map", "0:v", "-map", "1:a", .. secondSound ? (string[])["-map", "2:a"] : [],
                "-c:v", "libx264", "-preset", "ultrafast", "-c:a:0", "copy", .. secondSound ? (string[])["-c:a:1", "aac"] : [],
                path,
            ]);
        }
        finally
        {
            File.Delete(ac3);
        }

        var bytes = File.ReadAllBytes(path);
        for (var i = 0; i + 4 < bytes.Length; i++)
        {
            if (bytes[i] == 0x0B && bytes[i + 1] == 0x77)
            {
                bytes[i + 4] = 0xFF;
            }
        }

        File.WriteAllBytes(path, bytes);
    }

    private static void MakeCamcorderFileWithEmptySound(string path)
    {
        Run(s_tools.Ffmpeg,
        [
            "-hide_banner", "-loglevel", "error", "-nostdin", "-y",
            "-f", "lavfi", "-i", "testsrc=duration=1:size=176x144:rate=25",
            "-f", "lavfi", "-i", "sine=frequency=440:duration=1",
            "-c:v", "mpeg2video", "-c:a", "ac3", "-b:a", "64k", "-f", "vob", path,
        ]);
        var bytes = File.ReadAllBytes(path);
        var blanked = 0;
        for (var i = 0; i + 9 < bytes.Length; i++)
        {
            if (bytes[i] != 0 || bytes[i + 1] != 0 || bytes[i + 2] != 1 || bytes[i + 3] != 0xBD)
            {
                continue;
            }

            // After the PES header: the substream id, the frame count and the first access unit pointer, then AC-3.
            var end = Math.Min(bytes.Length, i + 6 + ((bytes[i + 4] << 8) | bytes[i + 5]));
            var start = i + 9 + bytes[i + 8] + 4;
            if (start >= end)
            {
                continue;
            }

            Array.Clear(bytes, start, end - start);
            blanked++;
            i = end - 1;
        }

        Assert.True(blanked > 0, "The generated file has no AC-3 packets to blank.");
        File.WriteAllBytes(path, bytes);
        Assert.Equal(["video", "audio"], StreamTypes(path));
    }

    // As the owner's camcorder files whose sound plays (D-087): MPEG-2 video and AC-3 sound at 48 kHz in a program stream.
    private static void MakeCamcorderFile(string path) =>
